//! Synthetic Globex sessions and test configurations shared by the test suites.
//!
//! The builders are deterministic and have no randomness of their own: the caller passes the
//! price steps and tick volumes, usually generated by proptest.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::indexing_slicing)]

use chrono::NaiveDate;
use vwap_core::{DataConfig, EventsConfig};
use vwap_data::{CleanBars, RawBars, clean::clean, time::utc_of_local};

/// The data configuration used by the tests: UTC timestamps, Globex anchor, tick volume weight.
pub fn data_config() -> DataConfig {
    toml::from_str(
        r#"
input_path = "x"
output_dir = "x"
artifact_dir = "x"
timestamp_kind = "utc"
server_offset_hours = 7
bar_label = "open"
session_anchor = "globex"
weight_column = "tick_volume"
price_grid = 0.1
drop_invalid_bars = true
roll_offset_days = 8
roll_buffer_sessions = 1
roll_confirm_percentile = 0.99
roll_search_window_days = 21
max_gap_minutes_ok = 2
max_gap_minutes_event = 5
outlier_z = 12.0
outlier_window_bars = 100
max_range_median_multiple = 40.0
min_bars_fraction = 0.9
early_close_time = "13:15"
flat_time_globex = "16:55"
flat_time_rth = "16:00"
expected_session_bars = 1380.0
"#,
    )
    .unwrap()
}

/// The events configuration used by the tests, with the re arm excursion and the exclusion
/// window as parameters.
pub fn events_config(rearm_k: f64, exclude_minutes: u32) -> EventsConfig {
    toml::from_str(&format!(
        r#"
timeframes = [5, 15]
atr_length = 14
rearm_k = {rearm_k}
exclude_minutes = {exclude_minutes}
vwap_reference = "bar_close"
output_dir = "x"
spotcheck_days = 1
spotcheck_seed = 1
spotcheck_dir = "x"
font_paths = ["x"]
spotcheck_min_session_minutes = 1000
"#
    ))
    .unwrap()
}

/// Bars from a price walk on the 0.1 grid. `steps` are in tenths of a point; the tick volume of
/// bar `i` is `weights[i] + 1`.
fn raw_walk(ts: Vec<i64>, steps: &[i32], weights: &[u8]) -> RawBars {
    assert_eq!(ts.len(), steps.len());
    assert_eq!(ts.len(), weights.len());
    let mut price = 18000.0f64;
    let (mut o, mut h, mut l, mut c) = (vec![], vec![], vec![], vec![]);
    for s in steps {
        let open = price;
        price = (price + f64::from(*s) * 0.1).max(1000.0);
        let close = (price * 10.0).round() / 10.0;
        o.push(open);
        c.push(close);
        h.push(open.max(close) + 0.2);
        l.push(open.min(close) - 0.2);
    }
    let n = ts.len();
    RawBars {
        ts_us: ts,
        open: o,
        high: h,
        low: l,
        close: c,
        volume: vec![0.0; n],
        tick_volume: weights.iter().map(|&w| f64::from(w) + 1.0).collect(),
        source_dtype: "test".into(),
    }
}

/// A single Globex session starting 2024-01-16 18:00 New York time, one bar per step, running
/// through midnight. Cleaned with the test data configuration.
pub fn session_bars(steps: &[i32], weights: &[u8]) -> CleanBars {
    let d0 = NaiveDate::from_ymd_opt(2024, 1, 16).unwrap();
    let (mut m, mut day) = (1080u32, d0);
    let mut ts = Vec::with_capacity(steps.len());
    for _ in 0..steps.len() {
        ts.push(utc_of_local(day, m).unwrap());
        m += 1;
        if m == 1440 {
            m = 0;
            day = day.succ_opt().unwrap();
        }
    }
    clean(&raw_walk(ts, steps, weights), &data_config())
        .unwrap()
        .0
}

/// Bars per full synthetic session of `multi_day_bars`: 18:00 to 17:00, 1380 minutes.
pub const BARS_PER_DAY: usize = 1380;

/// `days` consecutive full Globex sessions from the Monday 2024-01-15, each 18:00 to 16:59.
/// `steps` and `weights` must hold `days * BARS_PER_DAY` values.
pub fn multi_day_bars(days: usize, steps: &[i32], weights: &[u8]) -> CleanBars {
    let mut ts = Vec::with_capacity(days * BARS_PER_DAY);
    let mut anchor = NaiveDate::from_ymd_opt(2024, 1, 15).unwrap();
    for _ in 0..days {
        for m in 1080..1440u32 {
            ts.push(utc_of_local(anchor, m).unwrap());
        }
        let next = anchor.succ_opt().unwrap();
        for m in 0..1020u32 {
            ts.push(utc_of_local(next, m).unwrap());
        }
        anchor = next;
    }
    assert_eq!(ts.len(), days * BARS_PER_DAY);
    clean(&raw_walk(ts, steps, weights), &data_config())
        .unwrap()
        .0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_builders_produce_ordered_session_data_on_the_price_grid() {
        let steps: Vec<i32> = (0..500).map(|i| (i % 7) - 3).collect();
        let w = vec![5u8; 500];
        let b = session_bars(&steps, &w);
        assert_eq!(b.len(), 500);
        assert!(b.ts_us.windows(2).all(|p| p[0] < p[1]));
        assert!(
            b.close
                .iter()
                .all(|c| ((c * 10.0).round() - c * 10.0).abs() < 1e-6)
        );
        let m = multi_day_bars(2, &vec![0; 2 * BARS_PER_DAY], &vec![1; 2 * BARS_PER_DAY]);
        assert_eq!(m.len(), 2 * BARS_PER_DAY);
        // two distinct Globex sessions
        let mut s = m.globex_session.clone();
        s.dedup();
        assert_eq!(s.len(), 2);
    }
}
